-- Dense demo/test data — every real working day from 2026-06-30 to 2026-08-05
-- (2026) has at least 8 appointments, mixing booked slots with plenty still
-- reading as available. NOT real patients.
--
-- Supersedes the previous, sparser version of this file — running this
-- deletes that batch first (by its fixed 'd0000000-...' ids) before
-- inserting the new denser set, so it's safe to re-run even if you'd
-- already run the old one. Jun 30-Jul 27 and Aug 3-5 are entirely new
-- rows; Jul 28-31 gets just enough *additional* rows (new 'f0000000-...'
-- ids, at times that don't collide with the original seed-demo-data.sql
-- rows on those same 4 days) to bring each of those days up to 8+ too.
--
-- Run once in the Supabase SQL Editor (Dashboard -> SQL Editor -> New
-- query -> paste -> Run) against a project that already has schema.sql
-- applied. Every date/time below respects the clinic's real working
-- hours and closed days (lib/config.ts) and clinic timezone (+05:30).
--
-- Statuses are timing-aware relative to whenever you actually run this:
-- dates before today are COMPLETED/CANCELLED only (never an upcoming
-- CONFIRMED for a date that's already passed), dates after today are
-- CONFIRMED/CANCELLED only, and today itself splits by the clock.
--
-- To remove just this batch later:
--   delete from appointments where id::text like 'f0000000-0000-0000-0000-%';

delete from appointments where id::text like 'd0000000-0000-0000-0000-%';

insert into appointments (
  id, client_name, client_phone, start_time, end_time, status, notes,
  cancelled_by, cancellation_reason,
  prescription_notes, prescription_photo_url, prescription_slip_url, completed_at,
  created_at, updated_at
) values
